import { citypesearch } from "@/api/system/ciModel";
export default {
  props: ['formValue', 'showType'],
  data: function data() {
    return {
      typeList: [{
        name: '日期范围',
        value: 'daterange'
      }, {
        name: '时间范围',
        value: 'timerange'
      }, {
        name: '日期时间范围',
        value: 'datetimerange'
      }],
      formatList: [{
        value: 'yyyy-MM-dd'
      }, {
        value: 'MM-dd'
      }]
    };
  },
  created: function created() {
    if (this.showType == '新增') {
      this.formValue.config = {
        format: 'yyyy-MM-dd',
        type: 'daterange'
      };
    } else {
      if (this.formValue.config.type == 'daterange') {
        this.formatList = [{
          value: 'yyyy-MM-dd'
        }, {
          value: 'MM-dd'
        }];
      } else if (this.formValue.config.type == 'timerange') {
        this.formatList = [{
          value: 'HH:mm:ss'
        }];
      } else if (this.formValue.config.type == 'datetimerange') {
        this.formatList = [{
          value: 'yyyy-MM-dd HH:mm'
        }];
      }
    }
  },
  methods: {
    changeType: function changeType(val) {
      if (val == 'daterange') {
        this.formatList = [{
          value: 'yyyy-MM-dd'
        }, {
          value: 'MM-dd'
        }];
        this.formValue.config.format = 'yyyy-MM-dd';
      } else if (val == 'timerange') {
        this.formatList = [{
          value: 'HH:mm:ss'
        }];
        this.formValue.config.format = 'HH:mm:ss';
      } else if (val == 'datetimerange') {
        this.formatList = [{
          value: 'yyyy-MM-dd HH:mm'
        }];
        this.formValue.config.format = 'yyyy-MM-dd HH:mm';
      }
      this.$forceUpdate();
    }
  }
};
